INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('General', '¿Qué es SGAPE?', 'SGAPE es el Sistema de Gestión y Administración de Emprendimientos: una aplicación de escritorio para Windows y un bot de Telegram que ayudan a administrar nómina, inventario, ventas, finanzas, presupuestos y vacantes de uno o varios emprendimientos. Los datos viven en una base de datos Oracle en la nube.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('General', '¿Qué secciones tiene la aplicación?', 'El menú tiene: Inicio, Emprendimientos, Nómina, Vacantes, Inventario, Ventas, Finanzas, Presupuestos, Reportes y Telegram.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('General', '¿Dónde se guardan mis datos?', 'En la base de datos Oracle Autonomous Database (en la nube). Por eso puedes ver tu información desde otro computador con la aplicación o desde Telegram con el bot.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Cuenta', '¿Cómo creo una cuenta?', 'En la ventana de inicio de la aplicación elige "Crear cuenta" y escribe tu nombre, correo y una contraseña de al menos 8 caracteres con letras y números.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Telegram', '¿Cómo vinculo Telegram con mi cuenta?', 'En la aplicación entra a la sección Telegram y pulsa "Generar código". Luego escribe al bot /vincular seguido del código de 6 dígitos. El código vence en 10 minutos.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Telegram', '¿Qué puedo hacer desde el bot?', 'Ver el resumen del emprendimiento (/resumen), recibir el reporte en PDF (/reporte), revisar stock bajo (/stock), presupuestos (/presupuestos) y nómina (/nomina), cambiar de emprendimiento (/emprendimientos) y hacer preguntas en lenguaje natural. Registrar un gasto o un ingreso siempre pide confirmación.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Emprendimientos', '¿Cómo creo un emprendimiento?', 'En Emprendimientos pulsa "Nuevo". Escribe el nombre y elige el sector y la ciudad de las listas (puedes empezar a escribir y la lista te sugiere). La fecha de inicio no puede ser futura.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Emprendimientos', '¿Qué pasa si elimino un emprendimiento?', 'Se eliminan también sus cargos, trabajadores, productos, ventas, movimientos, presupuestos y vacantes. La aplicación pide confirmación antes de hacerlo.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Nómina', '¿Cómo creo un cargo?', 'En Nómina, pestaña Cargos, pulsa "Nuevo". La lista sugiere los cargos típicos del sector de tu emprendimiento con un salario sugerido que puedes ajustar.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Nómina', '¿Cómo registro un trabajador?', 'En Nómina, pestaña Trabajadores, pulsa "Nuevo". Elige el tipo de documento (CC, CE, TI, PA, PPT o PEP), escribe el número y elige el cargo. El número se valida según el tipo de documento.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Nómina', '¿Qué descuentos se aplican al salario?', 'Se descuenta 4 % de salud y 4 % de pensión, es decir 8 % del salario base. La nómina neta es el salario menos esas deducciones.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Vacantes', '¿Cómo publico una vacante?', 'En Vacantes pulsa "Nueva", elige el cargo y la ciudad y escribe una descripción. Los aspirantes la ven en el bot con /vacantes y envían su hoja de vida con /postular.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Vacantes', '¿Cómo envía un aspirante su hoja de vida?', 'El aspirante escribe al bot /vacantes, elige una y responde las preguntas: tipo y número de documento, nombre, teléfono, ciudad, autorización de tratamiento de datos (Ley 1581 de 2012) y por último envía su hoja de vida en PDF o Word. No necesita instalar la aplicación.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Vacantes', '¿Cómo reviso las postulaciones?', 'En Vacantes, selecciona la vacante y abre sus postulaciones. Puedes descargar la hoja de vida, marcarla en revisión, rechazarla o contratar al aspirante, lo que lo crea como trabajador.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Inventario', '¿Cómo agrego un producto?', 'En Inventario pulsa "Nuevo" y escribe nombre, categoría (la lista sugiere las que ya usas), precio de compra, precio de venta, stock inicial y stock mínimo.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Inventario', '¿Cómo registro entradas y salidas de stock?', 'Selecciona el producto y usa "Entrada" o "Salida". La entrada registra la compra en Finanzas automáticamente.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Inventario', '¿Qué significa stock bajo?', 'Que el stock está en o por debajo del stock mínimo que definiste. Aparece resaltado en Inventario, en Inicio y en el comando /stock del bot.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Inventario', '¿Puedo subir todos los precios a la vez?', 'Sí. En Inventario usa "Ajustar precios" y escribe un porcentaje (por ejemplo 5 para subir 5 % o -10 para bajar 10 %). Cada cambio queda en la auditoría de precios.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Ventas', '¿Cómo registro una venta?', 'En Ventas busca el producto (la lista te sugiere mientras escribes), indica la cantidad, agrégalo al carrito y pulsa "Registrar venta". La base de datos descuenta el stock y registra el ingreso en una sola transacción.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Ventas', '¿Puedo generar una factura?', 'Sí. En el historial de ventas selecciona la venta y pulsa "Factura PDF".');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Finanzas', '¿Cómo registro un ingreso o un gasto?', 'En Finanzas pulsa "Nuevo ingreso" o "Nuevo gasto" y elige la categoría de la lista. El monto debe ser mayor que cero y la fecha no puede ser futura.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Finanzas', '¿Qué es el balance?', 'Es la diferencia entre ingresos y gastos. Si es positivo hay utilidad; si es negativo conviene revisar los gastos o aumentar las ventas.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Presupuestos', '¿Cómo funcionan los presupuestos?', 'Defines un límite mensual para una categoría de gasto. El estado es OK, ALERTA cuando llegas al 80 % o EXCEDIDO cuando superas el límite. Solo puede haber un presupuesto por categoría y mes.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Reportes', '¿Qué hace la sección Reportes?', 'Muestra indicadores del emprendimiento y genera un reporte en PDF con ventas por mes, productos más vendidos, gastos por categoría, stock bajo y nómina. El mismo PDF lo envía el bot con /reporte.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Consejos', '¿Cómo fijo el precio de venta?', 'Suma el costo de compra y tus gastos por unidad, agrega el margen que quieres y compara con la competencia. En Inventario ves el margen de cada producto.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Consejos', '¿Qué hago si el balance es negativo?', 'Revisa en Finanzas las categorías de gasto más altas, define presupuestos con límite mensual e impulsa los productos con mejor margen.');
INSERT INTO sg_conocimiento (tema, pregunta, respuesta) VALUES ('Consejos', '¿Cómo evito quedarme sin mercancía?', 'Define un stock mínimo realista en cada producto y revisa a diario /stock en el bot o la pantalla de Inicio.');
